import { KansasCityApartmentMap } from './components/map/KansasCityApartmentMap';
import type { KansasCityMapHandle, ApartmentProperty } from './types/apartmentMap';

export function ApartmentSearchPage({ apartmentsFromGoogleSheet }: { apartmentsFromGoogleSheet: ApartmentProperty[] }) {
  const mapRef = useRef<KansasCityMapHandle>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [visibleProps, setVisibleProps] = useState<ApartmentProperty[]>([]);

  const handleCardClick = (prop: ApartmentProperty) => {
    setSelectedId(prop.id);
    // Tell the map component to focus/pan smoothly to this property
    mapRef.current?.focusProperty(prop.id, { zoom: 16, openInfoWindow: true });
  };

  return (
    <div className="flex h-screen w-full">
      {/* Surrounding Property Sidebar */}
      <aside className="w-96 overflow-y-auto p-4">
        <h2>Kansas City Apartments ({visibleProps.length} visible)</h2>
        {apartmentsFromGoogleSheet.map((prop) => (
          <div 
            key={prop.id} 
            onClick={() => handleCardClick(prop)}
            className={selectedId === prop.id ? 'border-blue-600 ring-2' : ''}
          >
            <h3>{prop.name}</h3>
            <p>\${prop.priceMin} - \${prop.priceMax}/mo</p>
          </div>
        ))}
      </aside>

      {/* Drop-in Google Maps Replacement Component */}
      <main className="flex-1 h-full relative">
        <KansasCityApartmentMap
          ref={mapRef}
          properties={apartmentsFromGoogleSheet}
          selectedPropertyId={selectedId}
          onSelectProperty={(prop) => setSelectedId(prop?.id || null)}
          onVisiblePropertiesChange={(visible) => setVisibleProps(visible)}
          mapType="roadmap"
          showStreetViewControl={true}
        />
      </main>
    </div>
  );
}`,o=`// How to pass your master Google Sheet data into the component:
